import { Injectable } from '@nestjs/common';
import { BizError, ErrorCode } from '@fw/core';
import type { PageQuery, PageResult, Where } from '@fw/db';
import { DemoItemRepository } from './demo-item.repository.js';
import type { DemoItem } from './demo-item.entity.js';
import type { CreateDemoItemInput, DemoItemQuery, UpdateDemoItemInput } from './demo-item.dto.js';

/** 默认每页条数（API 规格 §2：上限 100） */
const DEFAULT_PAGE_SIZE = 20;

@Injectable()
export class DemoItemService {
  constructor(private readonly repository: DemoItemRepository) {}

  /**
   * 分页查询：过滤条件下推 SQL，关键词走首个可搜索字符串字段的 like
   */
  async page(query: DemoItemQuery): Promise<PageResult<DemoItem>> {
    const { page = 1, pageSize = DEFAULT_PAGE_SIZE, keyword, ...filters } = query;
    const where: Where<DemoItem> = { ...filters };

    if (keyword) {
      where.title = { op: 'like', value: `%${keyword}%` };
    }

    const pageQuery: PageQuery<DemoItem> = {
      page: Number(page),
      pageSize: Math.min(Number(pageSize), 100),
      where,
    };
    return this.repository.pageDemoItems(pageQuery);
  }

  /** 详情：不存在抛 404（ErrorCode.NOT_FOUND） */
  async getById(id: string): Promise<DemoItem> {
    const found = await this.repository.findById(id);
    if (!found) {
      throw new BizError(ErrorCode.NOT_FOUND, 'DemoItem 不存在');
    }
    return found;
  }

  /** 新建：审计字段由 Repository 自动填充 */
  create(input: CreateDemoItemInput): Promise<DemoItem> {
    return this.repository.create(input);
  }

  /** 更新：先确认存在，避免对软删记录静默生效 */
  async update(id: string, patch: UpdateDemoItemInput): Promise<DemoItem> {
    await this.getById(id);
    return this.repository.update(id, patch);
  }

  /** 软删除（物理删除仅后台清理场景，业务代码禁用） */
  async remove(id: string): Promise<void> {
    await this.getById(id);
    await this.repository.softDelete(id);
  }
}
